import{_ as e,o as d,c as a,a2 as c}from"./chunks/framework.CTeY_0bQ.js";const p=JSON.parse('{"title":"更新记录","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":null}'),l={name:"changelog.md"};function s(t,o,i,r,n,h){return d(),a("div",null,[...o[0]||(o[0]=[c('<div><h1 id="更新记录" tabindex="-1">更新记录 <a class="header-anchor" href="#更新记录" aria-label="Permalink to &quot;更新记录&quot;">​</a></h1><p>laoshi 的版本号遵循语义化版本，从 0.1.0 开始；每一版的标题写成 <code>## &lt;版本&gt; - &lt;日期&gt;</code>。每一版先写使用者会看到的变化，再写升级须知。laoshi 之前的历史见 paseo-req-kit 的更新记录（laoshi 从它的 1.15.0 抽出）。</p><h2 id="_0-3-1-2026-11-27" tabindex="-1">0.3.1 - 2026-11-27 <a class="header-anchor" href="#_0-3-1-2026-11-27" aria-label="Permalink to &quot;0.3.1 - 2026-11-27&quot;">​</a></h2><p>正式版（npm <code>latest</code> 标签）：把共享 Web 需求看板直接内嵌到 DeepSeek Harness（<code>dsh</code>）左侧导航栏并支持全宽详情与 Paseo 一致化体验，增加会话顶部栏直达需求详情快捷入口与阶段执行记录跳回，修复 <code>dsh</code> 插件覆盖升级不生效，支持 Paseo 与 <code>dsh</code> 同机多平台并存，并完善一步安装与多平台自动升级体验。安装：<code>npx -y @yiyi_zhang/laoshi@latest install --platform &lt;dsh|paseo&gt;</code>。</p><h3 id="使用者会看到的变化" tabindex="-1">使用者会看到的变化 <a class="header-anchor" href="#使用者会看到的变化" aria-label="Permalink to &quot;使用者会看到的变化&quot;">​</a></h3><ul><li><strong>dsh 内嵌左侧栏「需求看板」与对话快捷直达</strong>：<code>laoshi-dsh-plugin</code> 在 <code>dsh</code> 左侧导航栏挂载 <strong>「需求看板」</strong>（<code>/laoshi/</code> 代理，自动随 <code>dsh</code> 切换深浅主题并复用登录校验）；在需求主对话或步骤子对话顶部工具栏展示 <strong>「需求：&lt;标题&gt;」</strong> 快捷按钮一键直达详情；详情中可从 <strong>「执行记录」</strong>（<code>查看执行记录 ↗</code>）或 <strong>「打开需求对话 ↗」</strong> 直接跳回对应子 agent 或原需求对话。</li><li><strong>Web 需求看板全宽详情与 Paseo 体验对齐</strong>：顶部新增 <strong>需求 / 使用统计 / 配置</strong> 导航切换；需求详情由 460px 右侧抽屉改为全宽页面（带 <code>← 返回需求列表</code>、关键决策高亮按钮、代码审查 / 审查原型外链、2 列元数据卡片、Markdown 渲染与 TSV 表格文档弹窗、完整执行记录与全宽验收/变更子页）。</li><li><strong>dsh 插件直接覆盖升级生效</strong>：再次运行 <code>laoshi install --platform dsh</code> 或 <code>laoshi upgrade</code> 时先移除并清理旧版 <code>laoshi-dsh-plugin</code>、校验并覆写最新文件，同时保留 <code>cordis.patch.yml</code> 中的 <code>approvals</code>、<code>board</code>、<code>boardPort</code> 并自动刷新 <code>kitRoot</code> 路径，无需手工先卸载旧插件。</li><li><strong>Paseo 与 dsh 同机多平台并存</strong>：同一台机器可先后安装多个平台，共用 <code>~/.laoshi/config.json</code> 与 <code>install.json</code>；运行时按 <code>LAOSHI_PLATFORM</code> 或对话环境变量（<code>DSH_SESSION_ID</code>、<code>PASEO_AGENT_ID</code>）自动切换适配器与平台级 <code>agents</code>；<code>laoshi doctor</code> 与 <code>laoshi install --platform &lt;id&gt; --uninstall</code> 支持分平台检查与单独卸载。</li><li><strong>真正的一步安装与多平台同步升级</strong>：<code>laoshi install --platform paseo</code> 现默认一并部署并加载 Paseo 需求插件（可用 <code>--no-plugin</code> 跳过，<code>--with-plugin</code> 兼容保留）；<code>laoshi upgrade</code> 或不带 <code>--platform</code> 执行 <code>laoshi install</code> 时会自动同步刷新所有已安装并存平台的 skill 与插件。</li><li><strong>升级前运行中需求检查（ADR 0007）</strong>：<code>laoshi upgrade</code> 在原地替换程序文件前自动扫描安装根索引下各代码库，列出等待中与运行中的流水线，存在本机运行中流水线时默认中止提醒（确认仍要继续可加 <code>--allow-running</code>）。</li><li><strong>契约、ADR 与文档同步</strong>：按 ADR 0008 修订 <code>contracts/agent-runtime.md</code>，将 ADR 0004/0006/0007/0008 定状态为 <code>已采纳</code>，并同步更新 Roadmap 与安装/升级/走查文档。</li></ul><h3 id="升级须知" tabindex="-1">升级须知 <a class="header-anchor" href="#升级须知" aria-label="Permalink to &quot;升级须知&quot;">​</a></h3><ul><li><strong>一步升级全部平台</strong>：在任意已安装机器运行 <code>laoshi upgrade</code>（公司内网镜像加 <code>--registry &lt;地址&gt;</code>），会自动升级到 <code>0.3.1</code> 并同步刷新本机所有已并存平台（Paseo / dsh）的 skill 与插件。</li><li><strong>内网离线包（Windows / dsh）</strong>：下载本版本 Release 附带的 <code>laoshi-0.3.1-&lt;commit&gt;-win32-x64.zip</code>，解压后直接覆盖运行 <code>node adapters\\dsh\\intranet\\install.mjs --profile web</code>，完成后重启 <code>dsh --profile web</code>。</li><li><strong>摸高</strong>：替换为本版本 Release 附带的 <code>laoshi-expert-0.3.1.zip</code>（或运行 <code>node adapters/mogao/make-expert.mjs</code> 重新生成）。</li></ul><h2 id="_0-3-1-beta-2-2026-11-25" tabindex="-1">0.3.1-beta.2 - 2026-11-25 <a class="header-anchor" href="#_0-3-1-beta-2-2026-11-25" aria-label="Permalink to &quot;0.3.1-beta.2 - 2026-11-25&quot;">​</a></h2><p>测试版（npm <code>beta</code> 标签，GitHub Pre-release）：修复 <code>dsh</code> 插件覆盖升级不生效、支持 <code>paseo</code> 与 <code>dsh</code> 同机多平台并存、在 <code>dsh</code> 会话顶部栏增加直达需求详情的快捷入口，并将 Web 看板升级为全宽详情与 Paseo 一致化视图。安装：<code>npx -y @yiyi_zhang/laoshi@beta install --platform dsh</code>。</p><h3 id="使用者会看到的变化-1" tabindex="-1">使用者会看到的变化 <a class="header-anchor" href="#使用者会看到的变化-1" aria-label="Permalink to &quot;使用者会看到的变化&quot;">​</a></h3><ul><li><strong>dsh 插件直接覆盖升级生效</strong>：再次运行 <code>laoshi install --platform dsh</code> 或 <code>laoshi upgrade</code> 时，会先清理旧的 <code>laoshi-dsh-plugin</code> 并按文件比对确保新版本文件完整覆盖，同时保留 <code>cordis.patch.yml</code> 中的 <code>approvals</code>、<code>board</code>、<code>boardPort</code> 并自动刷新 <code>kitRoot</code> 路径，无需再手工卸载旧版插件。</li><li><strong>Paseo 与 dsh 多平台并存（同份 <code>~/.laoshi/config.json</code>）</strong>：可在同一台机器先装一个平台后再装另一个平台（例如先装 <code>paseo</code> 再装 <code>dsh</code>）；运行时按 <code>LAOSHI_PLATFORM</code> 或平台对话环境变量（<code>DSH_SESSION_ID</code>、<code>PASEO_AGENT_ID</code>）自动切换适配器与 <code>platform.&lt;id&gt;.agents</code>；<code>laoshi doctor</code> 与 <code>laoshi install --platform &lt;id&gt; --uninstall</code> 支持分平台检查与单独卸载。</li><li><strong>dsh 对话顶部栏快捷直达需求详情</strong>：在发起需求的对话或步骤子对话中，顶部工具栏新增 <strong>「需求：&lt;标题&gt;」</strong> 快捷按钮，点击即可切换到 <strong>「需求看板」</strong> 面板并自动打开对应需求详情（新增 <code>/api/session-requirement</code> 与看板 <code>?open=</code> / <code>laoshi:open-requirement</code> 联动）。</li><li><strong>Web 需求看板全宽详情与 Paseo 体验对齐</strong>：顶部新增 <strong>需求 / 使用统计 / 配置</strong> 导航切换；需求详情由 460px 右侧抽屉改为全宽页面（带 <code>← 返回需求列表</code>、关键决策高亮按钮、代码审查 / 审查原型外链、位置/用量/质量门/外部系统 2 列元数据卡片、Markdown 渲染与 TSV 表格文档弹窗、完整执行记录与全宽验收/变更子页）。</li></ul><h3 id="升级须知-1" tabindex="-1">升级须知 <a class="header-anchor" href="#升级须知-1" aria-label="Permalink to &quot;升级须知&quot;">​</a></h3><ul><li><strong>直接升级 dsh 插件</strong>：无需卸载旧版，直接执行 <code>npx -y @yiyi_zhang/laoshi@beta install --platform dsh</code>（内网离线包运行对应安装脚本），完成后重启 <code>dsh --profile web</code>。</li><li><strong>与 Paseo 共存</strong>：如本机已安装 <code>paseo</code>，直接再执行 <code>laoshi install --platform dsh</code> 即可保留 <code>paseo</code> 默认配置并添加 <code>dsh</code> 并存配置。</li></ul><h2 id="_0-3-1-beta-1-2026-11-24" tabindex="-1">0.3.1-beta.1 - 2026-11-24 <a class="header-anchor" href="#_0-3-1-beta-1-2026-11-24" aria-label="Permalink to &quot;0.3.1-beta.1 - 2026-11-24&quot;">​</a></h2><p>测试版（npm <code>beta</code> 标签，GitHub Pre-release）：将共享 Web 需求看板直接内嵌到 DeepSeek Harness（<code>dsh</code>）Web 界面左侧导航栏，并支持从任务各阶段执行记录快捷跳回对应子 agent 对话或原需求对话。安装：<code>npx -y @yiyi_zhang/laoshi@beta install --platform dsh</code>。</p><h3 id="使用者会看到的变化-2" tabindex="-1">使用者会看到的变化 <a class="header-anchor" href="#使用者会看到的变化-2" aria-label="Permalink to &quot;使用者会看到的变化&quot;">​</a></h3><ul><li><strong>dsh 内嵌「需求看板」面板（<code>/laoshi/</code>）</strong>：<code>laoshi-dsh-plugin</code> 新增浏览器端界面模块（<code>adapters/dsh/plugin/client.js</code>）并在 <code>dsh</code> Web 服务端口挂载 <code>/laoshi</code> 代理，重启 <code>dsh</code> 后直接在左侧导航栏点击 <strong>「需求看板」</strong> 即可内嵌打开（自动同步 <code>dsh</code> 深浅主题、复用 <code>dsh</code> 登录认证校验，无需再单独打开页面）。</li><li><strong>任务阶段执行记录与原对话快捷跳转</strong>：共享看板详情抽屉新增 <strong>「执行记录」</strong>（展示各阶段状态、尝试次数、用时与错误信息，超过 12 步可切换查看全部）；在 <code>dsh</code> 中内嵌打开时，点击某一步的 <strong>「查看执行记录 ↗」</strong> 或顶部的 <strong>「打开需求对话 ↗」</strong> 可直接切回对应子 agent 或原需求对话。</li><li><strong>安装升级自动补齐与诊断增强</strong>：从旧版升级 <code>laoshi install --platform dsh</code> / <code>laoshi upgrade</code> 时，如 <code>cordis.patch.yml</code> 已挂载 <code>laoshi-dsh-plugin</code> 但缺少 <code>kitRoot</code> 或 <code>board</code>，会自动补齐并保留原有 <code>approvals</code> 等配置；<code>laoshi doctor</code> 同步提示 <code>/laoshi/</code> 左侧栏挂载状态。</li></ul><h3 id="升级须知-2" tabindex="-1">升级须知 <a class="header-anchor" href="#升级须知-2" aria-label="Permalink to &quot;升级须知&quot;">​</a></h3><ul><li><strong>内网 Windows / dsh 测试</strong>：运行 <code>npx -y @yiyi_zhang/laoshi@beta install --platform dsh</code>（或使用本版本 Release 附带的 Windows 离线安装包运行安装脚本），完成后重启 <code>dsh --profile web</code>，即可在左侧导航栏看到 <strong>「需求看板」</strong>。</li></ul><h2 id="_0-3-0-2026-11-24" tabindex="-1">0.3.0 - 2026-11-24 <a class="header-anchor" href="#_0-3-0-2026-11-24" aria-label="Permalink to &quot;0.3.0 - 2026-11-24&quot;">​</a></h2><p>正式版（npm <code>latest</code> 标签）：新增共享 Web 需求看板与验收工作台、全链路变更历史与转交、受控流程扩展、多仓库联合开发增强、预算预估与多模型评审检查，并将 Paseo（<code>0.11–0.17</code>）需求插件与 DeepSeek Harness（<code>dsh 0.2.2-alpha.2</code> / <code>0.2.2-rc.5</code>）宿主适配及文档补齐。安装：<code>npx -y @yiyi_zhang/laoshi@latest install --platform &lt;平台&gt;</code>。</p><h3 id="使用者会看到的变化-3" tabindex="-1">使用者会看到的变化 <a class="header-anchor" href="#使用者会看到的变化-3" aria-label="Permalink to &quot;使用者会看到的变化&quot;">​</a></h3><ul><li><strong>共享 Web 需求看板与验收工作台（<code>laoshi board</code>）</strong>：任意平台均可运行 <code>laoshi board</code> 打开本机实时中文 Bento 需求看板；支持总览分组、「需要你处理」置顶、需求详情 6 站放行轨，以及验收工作台（一键试用启停、逐条 AC 勾选与提交 <code>acceptance.md</code> 结论、证据预览）。安装时可通过 <code>dsh</code> 自动托管看板（默认启用 <code>board: true</code>，<code>--no-board</code> / <code>--board-port</code> 可选配置，<code>laoshi doctor</code> 直接显示访问地址）。</li><li><strong>改需求、变更历史与转交接手</strong>：Web 看板「变更与接手」页签、Paseo 插件详情页及 CLI（<code>laoshi reply --change</code>、<code>laoshi handover</code>）支持在需求推进中发起改需求、倒序查看 <code>changes.md</code> 变更历史与 <code>spec.md</code> 提交 diff（绿增/红删高亮），并支持转交接手及完整交接记录（<code>.pipeline/owner.json</code>）。</li><li><strong>受控流程扩展（<code>extensions</code>）</strong>：支持在项目配置 <code>.laoshi.json</code> 中向固定主阶段后挂载受控的 AI/skill 或脚本扩展步骤（注入 <code>LAOSHI_*</code> 环境变量，日志保留在 <code>.pipeline/extensions/</code>），并保持 Windows 下 <code>cmd.exe</code> 兼容。</li><li><strong>多仓库联合开发增强</strong>：支持配置 <code>maxJointRepos</code>（1–10），<code>/laoshi-setup</code> 自动发现同级 Git 仓库辅助配置，需求详情页直观展示各关联仓库分支、工作区路径与质量门状态。</li><li><strong>预算预估与多模型评审检查</strong>：开工前与看板详情提供历史同档位耗时 / token 预算预估及超预算提醒；启用多模型评审小组但配置缺失或仅单个提供方时由 <code>laoshi doctor</code> 提前告警。</li><li><strong>Paseo <code>0.11–0.17</code> 实机适配与插件体验</strong>：支持 <code>laoshi install --platform paseo --with-plugin</code> 一步部署并加载 Paseo 插件，插件与 Web 看板共享状态分组与文案，修复 Paseo 0.17 下服务端打包运行时缺少 <code>import.meta.url</code> 导致的插件 RPC 报错。</li><li><strong>dsh <code>0.2.2-rc.5</code> 适配与定时能力补齐</strong>：插件实现 <code>schedule</code> 的 <code>expiresAt</code> 到期自动取消及 <code>scheduleNewAgent</code> 独立定时会话；双版本兼容 <code>dsh 0.2.2-alpha.2</code> 与 <code>0.2.2-rc.5</code> 的 <code>startActivation</code>、<code>subagents.interrupt</code>、<code>schedule.create</code>/<code>edit</code>（含 <code>cron.time_zone</code>）与 <code>sessions.events</code>。</li><li><strong>摸高与通知体验打磨</strong>：摸高超长追问/打断消息写入文件兜底，同主机中断轮次自动续接；全部停顿通知统一附上【停下原因】与【下一步请说】提示；新增《Paseo Web 与 dsh 真实环境插件走查清单》及版本范围守护。</li></ul><h3 id="升级须知-3" tabindex="-1">升级须知 <a class="header-anchor" href="#升级须知-3" aria-label="Permalink to &quot;升级须知&quot;">​</a></h3><ul><li><strong>Paseo</strong>：运行 <code>laoshi upgrade</code> 升级到 <code>0.3.0</code>（支持 Paseo <code>0.11–0.17</code>；安装过插件时自动同步刷新并重载）。如果使用了非默认 <code>--home</code>，请在守护进程中设置 <code>LAOSHI_HOME</code> 或在 Paseo「设置 → 插件 → <code>laoshi 需求</code>」填写安装根路径。</li><li><strong>DeepSeek Harness（dsh）</strong>：运行 <code>laoshi upgrade</code> 升级到 <code>0.3.0</code>，同步更新 <code>laoshi-dsh-plugin</code>（同时兼容 <code>0.2.2-alpha.2</code> 与 <code>0.2.2-rc.5+</code>），并默认随宿主开启托管看板（可通过 <code>--no-board</code> 关闭）。</li><li><strong>摸高</strong>：替换为本版本 Release 附带的 <code>laoshi-expert-0.3.0.zip</code>（或运行 <code>node adapters/mogao/make-expert.mjs</code> 重新生成）。</li></ul><h2 id="_0-2-0-2026-11-21" tabindex="-1">0.2.0 - 2026-11-21 <a class="header-anchor" href="#_0-2-0-2026-11-21" aria-label="Permalink to &quot;0.2.0 - 2026-11-21&quot;">​</a></h2><p>正式版（npm <code>latest</code> 标签）：汇总 0.2.0-beta.1～beta.3 的全部功能（摸高适配器与专家包、Paseo 需求插件迁入、<code>laoshi migrate</code>、<code>laoshi permission</code>），并补充摸高版本自检、进程组清理、上下文控制、<code>laoshi diagnose</code> 脱敏诊断包与 Release 自动附带摸高专家包。安装：<code>npx -y @yiyi_zhang/laoshi@latest install --platform &lt;平台&gt;</code>。</p><h3 id="使用者会看到的变化-4" tabindex="-1">使用者会看到的变化 <a class="header-anchor" href="#使用者会看到的变化-4" aria-label="Permalink to &quot;使用者会看到的变化&quot;">​</a></h3><ul><li><strong>诊断包（<code>laoshi diagnose &lt;需求&gt; [--out &lt;目录&gt;]</code>）</strong>：一键导出已脱敏的排查目录（状态、流水线日志尾部、步骤结果、步骤输出与回调事件、脱敏配置与环境摘要），方便压缩后发给维护者定位问题。</li><li><strong>摸高：启动后不再&quot;去后台、有进展通知你&quot;</strong>：摸高上流水线在对话的命令里运行，对话一结束就停止。入口 skill 里启动后的说明改为摸高自己的一节（命令不会马上返回、不要结束这一轮对话、持续查看输出并转述）；命令输出也不再写&quot;已在后台启动&quot;&quot;进展会发回对话&quot;，安静超过 3 分钟时再提醒一次&quot;流水线仍在运行&quot;。</li><li><strong>摸高：结束一次运行时连它启动的进程一起结束</strong>：每次 <code>aimax run</code> 单独成一个进程组，结束时整组结束，步骤里留下的服务、构建守护进程不再残留；收到 <code>done</code> 回调后留 2 秒等待完整输出，避免抢跑拿到不完整回复与用量。</li><li><strong>步骤控制读入的内容量</strong>：步骤提示词要求命令输出先过滤再看、不整包解压或列出依赖包、读源码先搜索定位（有的模型实际上下文只有十万 token 左右）；因上下文占满失败重做时，告诉新的 agent 换做法，从已写下的产物接着做。方案写明依赖相关结论的依据（命令和关键输出），方案审核照着重跑核实、每个结论只核实一次、<code>javap</code> 不看常量池和字节码。</li><li><strong>摸高：专家要求的版本由命令自己保证</strong>：专家里每条 laoshi 命令都带上它要求的版本（<code>LAOSHI_WANT_VERSION</code>），工作区装的不是这个版本时，命令先从 npm 镜像装上再执行；安装失败时不会在子脚本里重复尝试，更新平台设置失败时给出明确警告。</li><li><strong>发布产物附带摸高专家包</strong>：GitHub Release 除 <code>.tgz</code> 与 Windows 离线包外，同时附带该版本生成的 <code>laoshi-expert-0.2.0.zip</code>。</li></ul><h3 id="升级须知-4" tabindex="-1">升级须知 <a class="header-anchor" href="#升级须知-4" aria-label="Permalink to &quot;升级须知&quot;">​</a></h3><ul><li><strong>摸高</strong>：直接替换为本版本 Release 附带的 <code>laoshi-expert-0.2.0.zip</code>（或运行 <code>node adapters/mogao/make-expert.mjs</code> 生成），不要手工修改旧专家包里的版本号。</li><li><strong>Paseo / dsh</strong>：运行 <code>laoshi upgrade</code> 即可升级到 <code>0.2.0</code>（Paseo 需求插件会顺带更新）。</li></ul><h2 id="_0-2-0-beta-3-2026-11-11" tabindex="-1">0.2.0-beta.3 - 2026-11-11 <a class="header-anchor" href="#_0-2-0-beta-3-2026-11-11" aria-label="Permalink to &quot;0.2.0-beta.3 - 2026-11-11&quot;">​</a></h2><p>预发布版（npm 的 <code>beta</code> 标签，<code>latest</code> 仍是 0.1.1）：摸高的回调按平台文档的格式解析，步骤做完后靠 <code>done</code> 及时进入下一步，工具调用和用量能收到。安装：<code>npx -y @yiyi_zhang/laoshi@beta install --platform &lt;平台&gt;</code>。</p><h3 id="使用者会看到的变化-5" tabindex="-1">使用者会看到的变化 <a class="header-anchor" href="#使用者会看到的变化-5" aria-label="Permalink to &quot;使用者会看到的变化&quot;">​</a></h3><ul><li><strong>摸高：回调按平台文档的格式解析</strong>：工具调用（包在 <code>progress</code> 事件里）现在收得到，危险命令拦截和&quot;最近活动&quot;在摸高上开始生效；用量从 <code>usage</code> 字段读并计入缓存命中；<code>error</code> 回调也表示运行结束；上一版启动、这一版接着等的步骤也能靠 <code>done</code> 及时结束。</li></ul><h3 id="升级须知-5" tabindex="-1">升级须知 <a class="header-anchor" href="#升级须知-5" aria-label="Permalink to &quot;升级须知&quot;">​</a></h3><ul><li>摸高：专家包要换成这个版本生成的（入口 skill 里写着要装的版本），第一次使用时会装上 0.2.0-beta.3；用 <code>node -p &quot;require(&#39;/data/workspace/.laoshi/npm/node_modules/@yiyi_zhang/laoshi/package.json&#39;).version&quot;</code> 确认。</li></ul><h2 id="_0-2-0-beta-2-2026-11-10" tabindex="-1">0.2.0-beta.2 - 2026-11-10 <a class="header-anchor" href="#_0-2-0-beta-2-2026-11-10" aria-label="Permalink to &quot;0.2.0-beta.2 - 2026-11-10&quot;">​</a></h2><p>预发布版（npm 的 <code>beta</code> 标签，<code>latest</code> 仍是 0.1.1）：修复摸高上步骤做完要等很久才进入下一步的问题；新增不需要平台的命令行 agent 适配器、<code>laoshi migrate</code> 和随 laoshi 发布的 Paseo 需求插件。安装：<code>npx -y @yiyi_zhang/laoshi@beta install --platform &lt;平台&gt;</code>。</p><h3 id="使用者会看到的变化-6" tabindex="-1">使用者会看到的变化 <a class="header-anchor" href="#使用者会看到的变化-6" aria-label="Permalink to &quot;使用者会看到的变化&quot;">​</a></h3><ul><li><strong>发起人</strong>：状态文件和 <code>laoshi api list</code> 记下每个需求的发起人（<code>startedBy</code>，第一次运行时为谁运行，之后不改）。</li><li><strong>使用者取平台给的身份</strong>：平台提供使用者时（摸高的 <code>AIMAX_USER_NAME</code>）优先用它，<code>LAOSHI_USER</code> 仍然最优先；<code>laoshi doctor</code> 显示使用者从哪里来。</li><li><strong>安装</strong>：程序装在安装根的 <code>npm</code> 目录里时（摸高专家就这样安装），不再提示&quot;需要设置环境变量 LAOSHI_HOME&quot;。</li><li><strong>命令行 agent（不需要平台）</strong>（<code>laoshi install --platform cli</code>）：步骤 agent 是 Claude Code（<code>claude -p</code>）或 Codex（<code>codex exec</code>）的一次运行，追问和打断用会话续接，工具调用来自命令行的事件流（危险命令拦截照常工作）；进展用 <code>laoshi status</code> 查看。第一版，真实命令行上的验证待做。</li><li><strong>摸高：步骤做完后马上进入下一步</strong>：agent 做完但 <code>aimax run</code> 进程不退出时，以完整的输出或平台回调的 <code>done</code> 为准结束这一步，并结束残留的进程（之前要等到平台结束后台命令、再继续时才进入下一步）。</li><li><strong>Paseo 的需求插件随 laoshi 发布</strong>：<code>laoshi plugin install|status|remove</code>（从 paseo-req-kit 迁入，插件 id 改为 <code>laoshi</code>）；安装、升级时顺带更新插件。</li><li><strong><code>laoshi migrate</code></strong>：从 paseo-req-kit 1.x 迁移本机的配置、使用记录、需求索引和需求状态；默认只预览，<code>--apply</code> 执行，<code>--rollback</code> 回滚；旧目录不动。</li><li><strong>文档</strong>：新增《在摸高上使用》《只用命令行 agent》。</li></ul><h3 id="升级须知-6" tabindex="-1">升级须知 <a class="header-anchor" href="#升级须知-6" aria-label="Permalink to &quot;升级须知&quot;">​</a></h3><ul><li>摸高：专家包要按这个版本重新生成（<code>node adapters/mogao/make-expert.mjs</code>），入口 skill 第一次使用时会换上这个版本。</li><li>Paseo：装过 paseo-req-kit 插件的，可以改装 laoshi 插件（<code>laoshi plugin install</code>），确认可用后用 <code>req plugin remove</code> 移除旧的。</li></ul><h2 id="_0-2-0-beta-1-2026-11-07" tabindex="-1">0.2.0-beta.1 - 2026-11-07 <a class="header-anchor" href="#_0-2-0-beta-1-2026-11-07" aria-label="Permalink to &quot;0.2.0-beta.1 - 2026-11-07&quot;">​</a></h2><p>预发布版（npm 的 <code>beta</code> 标签，<code>latest</code> 仍是 0.1.1）：支持摸高，用来在摸高沙箱里验证专家。安装：<code>npx -y @yiyi_zhang/laoshi@beta install --platform &lt;平台&gt;</code>。</p><h3 id="使用者会看到的变化-7" tabindex="-1">使用者会看到的变化 <a class="header-anchor" href="#使用者会看到的变化-7" aria-label="Permalink to &quot;使用者会看到的变化&quot;">​</a></h3><ul><li><strong>支持摸高</strong>（<code>laoshi install --platform mogao</code>）：每一步是摸高的一个独立 agent（<code>aimax run</code>），审批用摸高的人工审批，工具调用和用量来自摸高的进度回调。引擎在对话的命令里运行，进展显示在命令输出里；对话轮次结束打断的运行，下一轮用继续命令接着做。</li><li><strong>摸高专家</strong>：<code>node adapters/mogao/make-expert.mjs</code> 生成提交给摸高的专家（按摸高渲染的 skill 和介绍）；入口 skill 第一次使用时把 laoshi 装到工作区，并说明在摸高上命令会一直运行到停下、等待批准怎么回答、工具装在工作区。</li><li><strong>安装根</strong>：没有 <code>LAOSHI_HOME</code> 时，程序装在 <code>&lt;安装根&gt;/npm</code> 下就用这个安装根（每个对话轮次换机器的平台上不能依赖 <code>~</code>）。</li><li><strong><code>laoshi permission &lt;需求&gt; approve|deny [理由]</code></strong>：在对话里批准或拒绝步骤等待批准的操作，并接着运行（摸高上用）。</li><li><strong>危险命令拦截</strong>：读出凭据环境变量（如 <code>echo $XXX_TOKEN</code>、<code>printenv</code>）算作危险操作。</li></ul><h2 id="_0-1-1-2026-11-05" tabindex="-1">0.1.1 - 2026-11-05 <a class="header-anchor" href="#_0-1-1-2026-11-05" aria-label="Permalink to &quot;0.1.1 - 2026-11-05&quot;">​</a></h2><p>在 npm 上的包名改为 <strong><code>@yiyi_zhang/laoshi</code></strong>：<code>laoshi</code> 这个名字在 npm 上不能使用，0.1.0 只发布到了 GitHub Release，没有发布到 npm。其余内容与 0.1.0 相同。</p><h3 id="升级须知-7" tabindex="-1">升级须知 <a class="header-anchor" href="#升级须知-7" aria-label="Permalink to &quot;升级须知&quot;">​</a></h3><ul><li>安装命令：<code>npx -y @yiyi_zhang/laoshi@latest install --platform dsh|paseo</code>（内网加 <code>--registry=&lt;镜像地址&gt;</code>）。装好后的命令仍是 <code>laoshi</code>（别名 <code>req</code>），skill 仍是 <code>/laoshi</code> 等。</li><li>公司的 npm 镜像需要能同步 <code>@yiyi_zhang</code> 作用域下的包。</li><li>用 GitHub Release 上 0.1.0 的 <code>.tgz</code> 或离线包装过的机器，运行一次上面的安装命令即可换成 npm 上的版本。</li></ul><h2 id="_0-1-0-2026-11-05" tabindex="-1">0.1.0 - 2026-11-05 <a class="header-anchor" href="#_0-1-0-2026-11-05" aria-label="Permalink to &quot;0.1.0 - 2026-11-05&quot;">​</a></h2><p>第一个正式版：paseo-req-kit 的需求开发体系，抽成不绑定平台的工具包，支持 Paseo 和 DeepSeek Harness。</p><h3 id="使用者会看到的变化-8" tabindex="-1">使用者会看到的变化 <a class="header-anchor" href="#使用者会看到的变化-8" aria-label="Permalink to &quot;使用者会看到的变化&quot;">​</a></h3><ul><li><strong>新的名字和命令</strong>：对话中的入口是 <code>/laoshi</code>、<code>/laoshi-setup</code>、<code>/laoshi-doctor</code>、<code>/laoshi-retro</code>；终端命令是 <code>laoshi</code>（<code>req</code> 是它的别名）。</li><li><strong>支持 DeepSeek Harness（dsh）</strong>：步骤 agent 作为子会话挂在发起的对话下，进展和结果发回对话；各角色可以各用一个 dsh 中的模型（<code>&lt;提供方&gt;/&lt;模型&gt;</code>，<code>dsh/chat-model</code> 用对话的模型）；<code>laoshi doctor</code> 列出可用的模型并逐个角色检查。</li><li><strong>内置工作区和服务</strong>：平台不提供时，laoshi 用 <code>git worktree</code> 为需求新建工作区，并按 <code>.laoshi/services.json</code> 启动、检查、停止项目的服务（每个工作区独立端口）。</li><li><strong>一步安装</strong>：<code>npx -y @yiyi_zhang/laoshi@latest install --platform dsh|paseo</code>；公司内网加 <code>--registry=&lt;镜像地址&gt;</code>；<code>laoshi upgrade</code> 升级或回退；<code>laoshi install --check</code>、<code>--uninstall</code>。Windows 上只用 cmd 和 Git Bash。</li><li><strong>离线安装包</strong>：完全没有 npm 源的机器，用 GitHub Release 上带 Windows 依赖的离线安装包，步骤见&quot;内网安装与验证&quot;。</li><li><strong>文档站点</strong>：<a href="https://yiyisf.github.io/laoshi/" target="_blank" rel="noreferrer">https://yiyisf.github.io/laoshi/</a> ；<code>laoshi docs</code> 在本机打开和装的版本一致的文档（不需要外网）。</li><li><strong>体检</strong>：<code>laoshi doctor</code> 的&quot;安装&quot;一节检查 skill 是否已是这个版本的，并从 npm 源查询有没有新版本。</li><li><strong>使用记录带上代码库和使用者</strong>：使用记录、通知事件和 <code>laoshi api list</code> 中增加了代码库（目录、远程地址）和使用者（<code>LAOSHI_USER</code> 或安装级配置的 <code>user</code>）。</li></ul><h3 id="升级须知-从-paseo-req-kit" tabindex="-1">升级须知（从 paseo-req-kit） <a class="header-anchor" href="#升级须知-从-paseo-req-kit" aria-label="Permalink to &quot;升级须知（从 paseo-req-kit）&quot;">​</a></h3><ul><li>laoshi 和 paseo-req-kit 可以装在同一台机器上，互不覆盖：安装根是 <code>~/.laoshi</code>（只有 <code>~/.req-kit</code> 时读取它），项目配置是 <code>.laoshi.json</code>（<code>.requirement-pipeline.json</code> 继续被读取）。</li><li>状态文件升到第 2 版：第一次读到旧的状态文件时自动迁移，原文件留作 <code>.bak-v1</code>；正在运行的流水线只在内存中迁移。</li><li>配置中的 <code>paseoProfile</code>、<code>paseoServices</code> 改名为 <code>platformProfile</code>、<code>platformServices</code>，旧名继续有效。</li><li>Paseo 的需求插件暂时仍由 paseo-req-kit 提供，计划在 0.1.0 之后迁入。</li></ul></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/laoshi/blob/main/CHANGELOG.md">CHANGELOG.md</a> 生成。<a href="https://github.com/yiyisf/laoshi/edit/main/CHANGELOG.md">在 GitHub 上编辑</a></p>',2)])])}const u=e(l,[["render",s]]);export{p as __pageData,u as default};
